'use strict';
const {rows,audit,excluded}=window.RADAR;
const $=s=>document.querySelector(s),money=n=>'$'+(n>=1e9?(n/1e9).toFixed(2)+'B':n>=1e6?(n/1e6).toFixed(1)+'M':(n/1e3).toFixed(0)+'K');
const esc=s=>String(s??'—').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const storage={get(k,f){try{return JSON.parse(localStorage.getItem(k))??f}catch{return f}},set(k,v){try{localStorage.setItem(k,JSON.stringify(v))}catch{}}};
const saved=new Set(storage.get('signal-saved',[]));let page=0,watchOnly=false,savedOnly=false,filtered=rows;const size=8;
const date=new Date(audit.as_of+'T00:00:00Z').toLocaleDateString('en-GB',{day:'2-digit',month:'short',year:'numeric',timeZone:'UTC'});
$('#asof').textContent=date;$('#rail-date').textContent=audit.as_of;$('#coverage').textContent=audit.protocols+' records / one fixed point in time';$('#count').textContent=rows.length;$('#watch').textContent=audit.watchlist+' / '+audit.watchlist;$('#peers').textContent=audit.peers;$('#error').textContent=audit.error_factor.toFixed(1)+'×';
for(const c of [...new Set(rows.map(x=>x.category))].sort())$('#category').insertAdjacentHTML('beforeend',`<option>${esc(c)}</option>`);
for(const c of [...new Set(rows.flatMap(x=>x.chains))].sort())$('#chain').insertAdjacentHTML('beforeend',`<option>${esc(c)}</option>`);
function change(n){return n===null?'<span class="num">Unreported</span>':`<span class="num ${n>=0?'up':'down'}">${n>=0?'+':''}${n.toFixed(2)}%</span>`;}
function draw(){const q=$('#search').value.toLowerCase().trim(),c=$('#category').value,ch=$('#chain').value;filtered=rows.filter(r=>(!q||(r.name+' '+r.chains.join(' ')).toLowerCase().includes(q))&&(!c||r.category===c)&&(!ch||r.chains.includes(ch))&&(!watchOnly||r.watchlist)&&(!savedOnly||saved.has(r.slug)));page=Math.min(page,Math.max(0,Math.ceil(filtered.length/size)-1));$('#result-count').textContent=filtered.length;$('#saved-count').textContent=saved.size;$('#watch-toggle').setAttribute('aria-pressed',watchOnly);$('#saved-toggle').setAttribute('aria-pressed',savedOnly);$('#rows').innerHTML=filtered.slice(page*size,(page+1)*size).map(r=>`<tr data-slug="${esc(r.slug)}" tabindex="0" aria-label="Open ${esc(r.name)} detail"><td class="rank-num">${String(r.rank).padStart(2,'0')}</td><td><div class="protocol"><div class="avatar c${r.rank%4}">${esc(r.name.split(/[- ]/).map(w=>w[0]).slice(0,2).join('').toUpperCase())}</div><div><strong>${esc(r.name)}</strong>${r.watchlist?'<i class="house" title="Official house watchlist"></i>':''}<small>${esc(r.category)} · ${esc(r.chains[0])}${r.chains.length>1?' +'+(r.chains.length-1):''}</small></div></div></td><td class="num">${money(r.tvl_usd)}</td><td>${change(r.change_7d)}</td><td><span class="value">${money(r.implied_value_usd)}</span><span class="range">${money(r.low_usd)} – ${money(r.high_usd)}</span></td><td><span class="evidence">${r.model.n} category peers · ${r.confidence}</span><div class="bar"><i style="width:${Math.max(7,r.model.weight*100)}%"></i></div></td><td><button class="save ${saved.has(r.slug)?'on':''}" data-save="${esc(r.slug)}" aria-label="Save ${esc(r.name)}">${saved.has(r.slug)?'★':'☆'}</button><button class="row-arrow" aria-label="Open detail">↗</button></td></tr>`).join('');$('#empty').hidden=filtered.length>0;$('#page-info').textContent=filtered.length?`${page*size+1}–${Math.min((page+1)*size,filtered.length)} of ${filtered.length} protocols · teal dot = house watchlist`:'0 protocols';$('#prev').disabled=page===0;$('#next').disabled=(page+1)*size>=filtered.length;}
function filter(){page=0;draw()}
$('#search').addEventListener('input',filter);$('#category').onchange=filter;$('#chain').onchange=filter;$('#watch-toggle').onclick=()=>{watchOnly=!watchOnly;filter()};$('#saved-toggle').onclick=()=>{savedOnly=!savedOnly;filter()};$('#reset').onclick=()=>{$('#search').value='';$('#category').value='';$('#chain').value='';watchOnly=savedOnly=false;filter()};$('#prev').onclick=()=>{page--;draw()};$('#next').onclick=()=>{page++;draw()};
function toggleSave(slug){saved.has(slug)?saved.delete(slug):saved.add(slug);storage.set('signal-saved',[...saved]);draw();}
$('#rows').onclick=e=>{const b=e.target.closest('[data-save]');if(b){toggleSave(b.dataset.save);return}const tr=e.target.closest('tr');if(tr)openDetail(tr.dataset.slug)};$('#rows').onkeydown=e=>{if(e.key==='Enter'&&e.target.matches('tr'))openDetail(e.target.dataset.slug)};
function openDetail(slug){const r=rows.find(x=>x.slug===slug);if(!r)return;const m=r.model;const checked=storage.get('signal-plan-'+slug,[]);$('#detail-body').innerHTML=`<div class="detail-top"><div><div class="label">PROTOCOL BRIEF / #${String(r.rank).padStart(2,'0')} <span class="tag">${r.watchlist?'HOUSE WATCHLIST':'EARLY / REVIEW PARENT'}</span></div><h2>${esc(r.name)} <span class="accent">↗</span></h2><p>${esc(r.category)} &nbsp; / &nbsp; ${esc(r.chains.join(' · '))}</p></div><button class="close" aria-label="Close protocol detail">✕</button></div><div class="detail-grid"><div><div class="label">CONDITIONAL CIRCULATING MARKET CAP</div><div class="detail-value">${money(r.implied_value_usd)} <small>not FDV</small></div><p class="subtle">What a token could be valued at if this protocol traded at its blended peer multiple. Not the value of a user allocation.</p><div class="ribbon"><span>80% peer residual range</span><strong>${money(r.low_usd)} – ${money(r.high_usd)}</strong></div><div class="facts"><div><span>TVL</span><strong>${money(r.tvl_usd)}</strong></div><div><span>7D TVL</span><strong>${change(r.change_7d)}</strong></div><div><span>LISTED</span><strong>${esc(r.listed_at||'Unreported')}</strong></div></div><div class="section-label">THE VALUATION BRIDGE</div><div class="formula">${money(r.tvl_usd)} TVL × ${m.multiple.toFixed(3)}× blended multiple<br>Category ${m.local.toFixed(3)}× (${(m.weight*100).toFixed(0)}% weight)<br>Global ${m.global.toFixed(3)}× (${((1-m.weight)*100).toFixed(0)}% weight)<br>Weight = ${m.n} category peers / (${m.n} + 6)</div><div class="section-label">${m.n?'NEAREST CATEGORY':'GLOBAL FALLBACK'} PEERS · MCAP / TVL</div><table class="comps">${m.comps.map(x=>`<tr><td>${esc(x.name)}</td><td>${money(x.mcap)}</td><td>${x.ratio.toFixed(2)}×</td></tr>`).join('')}</table><div class="warning"><strong>Eligibility is a record, not a fact.</strong><br>${esc(r.eligibility)}</div></div><div><div class="plan-title"><h3>A deliberate farming plan</h3><span id="progress">${checked.length} / ${r.farm_steps.length} REVIEWED</span></div><p class="subtle">A cautious product-use checklist. No confirmed points, airdrop, token date or allocation is present in the sealed data.</p><ol class="plan-list">${r.farm_steps.map((x,i)=>`<li><input type="checkbox" aria-label="Mark step ${i+1} reviewed" data-step="${i}" ${checked.includes(i)?'checked':''}><div><span class="label">0${i+1} / ${['VERIFY THE VENUE','CHECK ELIGIBILITY','TEST THE PRODUCT','TRACK, DON’T SPAM','SET THE EXIT'][i]}</span><br>${esc(x)}</div></li>`).join('')}</ol><div class="warning"><strong>Before you allocate</strong><br>No contract addresses or reward rules are supplied by this dataset. Verify independently. Avoid leverage, Sybil activity and any strategy whose fees require a token payout to break even.</div><button class="quiet" id="save-detail" style="margin-top:15px">${saved.has(slug)?'★ Saved to shortlist':'☆ Save to shortlist'}</button></div></div><div class="detail-foot"><span>SNAPSHOT ${audit.as_of} · MODEL 01 · ${r.confidence.toUpperCase()} CATEGORY EVIDENCE</span><span>Not investment advice</span></div>`;$('#detail .close').onclick=()=>$('#detail').close();$('#save-detail').onclick=()=>{toggleSave(slug);$('#save-detail').textContent=saved.has(slug)?'★ Saved to shortlist':'☆ Save to shortlist'};$('#detail-body').onchange=e=>{if(!e.target.matches('[data-step]'))return;const arr=[...$('#detail-body').querySelectorAll('[data-step]:checked')].map(x=>+x.dataset.step);storage.set('signal-plan-'+slug,arr);$('#progress').textContent=arr.length+' / '+r.farm_steps.length+' REVIEWED'};if(!$('#detail').open)$('#detail').showModal();$('#detail').scrollTop=0;}
